def seed(apps, schema_editor=None):
    from django.conf import settings

    Pack = apps.get_model("library", "ContentPack")
    Table = apps.get_model("library", "ScenarioTable")
    Entry = apps.get_model("library", "ScenarioEntry")
    pack, _ = Pack.objects.get_or_create(
        slug=settings.DEFAULT_CONTENT_PACK_SLUG,
        defaults={"name": settings.DEFAULT_CONTENT_PACK_NAME},
    )
    for source in CONTENT:
        fields = {
            key: value for key, value in source.items() if key not in ("key", "entries")
        }
        table, _ = Table.objects.get_or_create(
            legacy_key=source["key"], defaults={**fields, "pack_id": pack.pk}
        )
        for entry in source["entries"]:
            Entry.objects.get_or_create(
                table_id=table.pk,
                roll=entry["roll"],
                defaults={
                    **{key: value for key, value in entry.items() if key != "roll"},
                    "pack_id": pack.pk,
                },
            )


